// Parse the agent's stdout for the cycle summary line and surface a Telegram note only when something happened.
const out = ($input.item.json.stdout || '') + '';
const m = out.match(/Cycle complete: (\{.*\})/);
let summary = {};
try { if (m) summary = JSON.parse(m[1].replace(/'/g, '"')); } catch (e) {}
const commander = summary.commander || 0;
const drafted = summary.client_drafted || 0;
const errors = summary.errors || 0;
const notify = commander > 0 || drafted > 0 || errors > 0;
const ts = new Date().toLocaleString('en-US', { timeZone: 'America/Denver', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
let message = '';
if (notify) {
  const parts = [];
  if (commander) parts.push(`${commander} Commander repl${commander > 1 ? 'ies' : 'y'} sent`);
  if (drafted) parts.push(`${drafted} client draft${drafted > 1 ? 's' : ''} staged (WF-17)`);
  if (errors) parts.push(`\u26a0\ufe0f ${errors} error${errors > 1 ? 's' : ''}`);
  message = `*D2M Email Loop \u2014 ${ts} MT*\n${parts.join('\n')}`;
}
return [{ json: { notify, message, summary } }];
